<script setup lang="ts">import { onMounted } from 'vue';import { usePlansStore } from './stores/plans';import PlanCard from './components/PlanCard.vue';import EstimatePanel from './components/EstimatePanel.vue';const store=usePlansStore();onMounted(store.load);const money=(n:number)=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:0}).format(n);</script>
